<template><div class="min-h-screen overflow-hidden bg-[#080b14] text-slate-100"><header class="fixed inset-x-0 top-0 z-50 border-b border-white/[0.07] bg-[#080b14]/85 backdrop-blur-xl"><nav class="container-wide flex h-[76px] items-center justify-between"><a href="#/" class="flex items-center gap-3" @click="closeMenu"><span class="grid h-10 w-10 place-items-center rounded-xl border border-violet-300/25 bg-violet-400/10 font-bold text-violet-200">HJ</span><span class="text-sm font-semibold tracking-wide">Harshil Jani</span></a><button class="rounded-lg border border-white/10 px-3 py-2 text-sm md:hidden" @click="menuOpen=!menuOpen" aria-label="Toggle navigation">Menu</button><div class="hidden items-center gap-8 text-sm text-slate-300 md:flex"><a href="#" @click.prevent="scrollToSection('about')" class="hover:text-white">About</a><a href="#" @click.prevent="scrollToSection('skills')" class="hover:text-white">Skills</a><a href="#" @click.prevent="scrollToSection('experience')" class="hover:text-white">Experience</a><a href="#" @click.prevent="scrollToSection('projects')" class="hover:text-white">Projects</a><a href="#" @click.prevent="scrollToSection('contact')" class="rounded-full border border-violet-300/30 bg-violet-300/10 px-4 py-2 font-medium text-violet-100 hover:bg-violet-300/20">Contact</a></div></nav><div v-if="menuOpen" class="border-t border-white/10 bg-[#0b1020] px-5 py-4 md:hidden"><div class="container-wide flex flex-col gap-4 text-sm text-slate-300"><a href="#" @click.prevent="scrollToSection('about')" @click="closeMenu">About</a><a href="#" @click.prevent="scrollToSection('skills')" @click="closeMenu">Skills</a><a href="#" @click.prevent="scrollToSection('experience')" @click="closeMenu">Experience</a><a href="#" @click.prevent="scrollToSection('projects')" @click="closeMenu">Projects</a><a href="#" @click.prevent="scrollToSection('contact')" @click="closeMenu">Contact</a></div></div></header><main class="pt-[76px]"><slot/></main><footer class="border-t